/**
 * What Apple and Google need before an app can be built for them, and what each thing is.
 *
 * None of this can be generated by the platform. A distribution certificate, a provisioning profile and an
 * App Store Connect key all come from an Apple Developer Program account; the Play service account comes
 * from a Google Play Console. So the platform's job is to say exactly what is missing, take the files, and
 * put them where the build can reach them — never to pretend it can make them.
 *
 * Everything here is stored as a GitHub Actions secret on the build repository, sealed to the repository's
 * public key before it leaves the platform. Nothing is kept in the database, and GitHub never hands a
 * secret's value back, so the panel can show that a secret exists but never what it contains.
 */

export type CredKind = "text" | "file" | "password";

export interface Cred {
  key: string; // the repository secret's name
  label: string;
  kind: CredKind;
  /** How somebody actually gets this. Shown under the field, because "IOS_CERT_P12_BASE64" tells nobody. */
  help: string;
  /** A file is base64-encoded before it is sent, since a secret is text. */
  accept?: string;
  optional?: boolean;
}

export interface CredGroup {
  id: "ios" | "ios_store" | "play" | "push";
  title: string;
  /** What switches on once every non-optional credential in the group is present. */
  unlocks: string;
  /** Where these come from, in one sentence. */
  from: string;
  creds: Cred[];
}

