/** Android direct-install builds need none of this — the platform makes and keeps that key itself. */
export const ALL_CRED_KEYS = CRED_GROUPS.flatMap((g) => g.creds.map((c) => c.key));

export const groupReady = (g: CredGroup, present: string[]) => g.creds.filter((c) => !c.optional).every((c) => present.includes(c.key));
